mkdir -p /tmp/bot-test && cat > /tmp/bot-test/test.mjs <<'EOF'
import assert from "node:assert/strict";
import { onInbound, check } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-inv-g5-2/bot.mjs";

const H = 3600_000;
const t0 = new Date("2026-10-23T10:00:00Z");
const at = (h) => new Date(t0.getTime() + h * H);
let n = 0;
const ok = (name, fn) => { fn(); n++; console.log("ok -", name); };

ok("never-written user: freeform and template both blocked", () => {
  assert.deepEqual(check("new1", "freeform", at(0)), { allowed: false, rule: "no_prior_inbound" });
  assert.deepEqual(check("new1", "template", at(0)), { allowed: false, rule: "no_prior_inbound" });
});

ok("freeform allowed inside 24h, blocked at and after 24h", () => {
  onInbound("u1", "my bill is wrong", at(0));
  assert.deepEqual(check("u1", "freeform", at(23.99)), { allowed: true, rule: null });
  assert.deepEqual(check("u1", "freeform", at(24)), { allowed: false, rule: "outside_24h_window" });
});

ok("template allowed outside window", () => {
  assert.deepEqual(check("u1", "template", at(100)), { allowed: true, rule: null });
});

ok("window is measured from latest inbound, not out-of-order older one", () => {
  onInbound("u2", "hi", at(10));
  onInbound("u2", "hello", at(5)); // arrives late, older
  assert.equal(check("u2", "freeform", at(33.5)).allowed, true);
  assert.equal(check("u2", "freeform", at(34)).allowed, false);
});

ok("STOP variants opt out all types, case/punctuation/spacing insensitive", () => {
  for (const msg of ["STOP", "stop", " Stop! ", "s.t.o.p", "Stop.", "STOP 🛑", "opt out", "OPT-OUT", "stop all", "Unsubscribe", "cancel", "END", "quit"]) {
    onInbound("u3", "x", at(1)); // make window open so only opt-out matters
    onInbound("u3", msg, at(2));
    assert.deepEqual(check("u3", "freeform", at(3)), { allowed: false, rule: "opted_out" }, msg);
    assert.deepEqual(check("u3", "template", at(3)), { allowed: false, rule: "opted_out" }, msg);
    onInbound("u3", "START", at(2.5)); // reset for next iteration
  }
});

ok("ordinary sentences containing keywords do not opt out", () => {
  for (const msg of ["please stop texting me", "I can't stop by today", "the end of the month", "don't cancel my plan", "yes I want it", "quitting my job"]) {
    onInbound("u4", msg, at(1));
    assert.equal(check("u4", "template", at(2)).allowed, true, msg);
  }
});

ok("START / UNSTOP / YES restore sending", () => {
  onInbound("u5", "STOP", at(1));
  assert.equal(check("u5", "template", at(2)).allowed, false);
  onInbound("u5", "start", at(3));
  assert.equal(check("u5", "template", at(4)).allowed, true);
  onInbound("u5", "STOP", at(5));
  onInbound("u5", "Unstop", at(6));
  assert.equal(check("u5", "template", at(7)).allowed, true);
  onInbound("u5", "STOP", at(8));
  onInbound("u5", "YES.", at(9));
  assert.equal(check("u5", "template", at(10)).allowed, true);
});

ok("START also opens the freeform window", () => {
  onInbound("u6", "STOP", at(1));
  onInbound("u6", "START", at(2));
  assert.equal(check("u6", "freeform", at(3)).allowed, true);
});

ok("opt-out that is older than the latest opt change is ignored", () => {
  onInbound("u7", "START", at(5));
  onInbound("u7", "STOP", at(4)); // arrives late, older than START
  assert.equal(check("u7", "template", at(6)).allowed, true);
});

ok("invalid type fails closed; bad Dates throw", () => {
  assert.deepEqual(check("u1", "sms", at(1)), { allowed: false, rule: "invalid_type" });
  assert.throws(() => onInbound("u1", "x", "2026-10-23"), TypeError);
  assert.throws(() => check("u1", "freeform", new Date("nope")), TypeError);
});

ok("users are isolated", () => {
  assert.equal(check("u3", "template", at(3)).allowed, false);
  assert.equal(check("u1", "template", at(3)).allowed, true);
});

console.log(`\n${n} groups passed`);
EOF
